changeSet.sql:
DO $$
DECLARE
    linha RECORD;
BEGIN
    FOR linha IN SELECT id FROM entidade WHERE codigo IS NULL ORDER BY id LOOP
        BEGIN
            DELETE FROM entidade WHERE id = linha.id;
        EXCEPTION WHEN foreign_key_violation THEN
            RAISE EXCEPTION 'A entidade com id % não tem código no extrato da DGT e está referenciada por outras tabelas. Recrie a base de desenvolvimento com scripts/reset-all.sh.', linha.id;
        END;
    END LOOP;
END $$;

ALTER TABLE entidade DROP CONSTRAINT ck_entidade_tipo_entidade;
ALTER TABLE entidade ADD CONSTRAINT ck_entidade_tipo_entidade CHECK (
tipo_entidade IN ('CM', 'CCDR_DR', 'AM', 'CIM', 'PCM', 'SEC_ESTADO', 'DGT', 'ICNF', 'APA', 'DGPC', 'IP'));
ALTER TABLE entidade ADD CONSTRAINT ck_entidade_dico_cm CHECK (dico IS NULL OR tipo_entidade = 'CM')

rollback.sql:
ALTER TABLE entidade DROP CONSTRAINT ck_entidade_dico_cm;
ALTER TABLE entidade DROP CONSTRAINT ck_entidade_tipo_entidade;
ALTER TABLE entidade ADD CONSTRAINT ck_entidade_tipo_entidade CHECK (tipo_entidade IS NULL OR
tipo_entidade IN ('CM', 'CCDR_DR', 'AM', 'CIM', 'PCM', 'SEC_ESTADO', 'DGT', 'ICNF', 'APA', 'DGPC', 'IP'))
